from __future__ import annotations
import argparse
import csv
import html
import json
from pathlib import Path
import statistics


def main():
    parser=argparse.ArgumentParser();parser.add_argument('review_root');a=parser.parse_args()
    root=Path(a.review_root)
    summary=json.loads((root/'summary.json').read_text())
    identity=json.loads((root/'run_identity.json').read_text())
    validation=json.loads((root/'adapter_validation.json').read_text())
    with (root/'comparison.csv').open() as f:cases=list(csv.DictReader(f))
    groups={'old_two':'old method: both knees succeeded','old_one':'old method: only one side succeeded','old_zero':'old method: both knees failed','new_position':'added by position split'}
    notes=[]
    for row in cases:
        cid=row['case_id'];g=row['group']
        if g=='old_two':note='Both methods cover the visible joint region. YOLO is tighter; the existing method keeps more of the upper and lower bone.'
        elif g=='old_one':note='The old method rejected one side because the required box exceeded the source field of view; YOLO outputs both sides and the added joint is visible.'
        elif g=='old_zero':note='The old method refused to output because the two independent height estimates disagreed; the joint region output by YOLO is visible.'
        else:note='Added by the position split. YOLO outputs both knees with tighter crops; the clinical side labels are not checked here.'
        if cid=='C05':note='YOLO missed the image-right side; the old method shows that joint clearly. Direct replacement can still lose samples that were previously croppable.'
        if cid=='C39':note='The current gray input is severely washed out. YOLO outputs only the image-left box, and its detail is not enough for a reliable review; image right is missed. The gray chain and the original film must be checked; this box cannot count as confirmed usable.'
        if cid in ['C10','C31','C38']:note+=' The current input is bright with weak detail; producing a box does not solve the gray quality problem.'
        if cid=='C30':note+=' The resampled size of this case is smaller than the author center window, so the detector input is zero-padded; this deviation is recorded.'
        if cid=='C33':note+=' The mask at the bottom of the full-image preview is for display only; the single-knee crops come from native pixels.'
        if cid=='C44':note='The old method rejected both sides because the required boxes exceeded the source field of view; YOLO outputs both sides and the joint regions are visible.'
        notes.append({'case_id':cid,'group':g,'group_zh':groups[g],'old_count':int(row['old_count']),'yolo_count':int(row['yolo_count']),
            'modality':row['modality'],'visit':row['visit'],'note':note,'needs_attention':cid in ['C05','C10','C30','C31','C38','C39'],
            'review_type':'AI technical visual inspection; no expert reference boxes; no KL grading'})
    (root/'visual_review.json').write_text(json.dumps({'reviewed_panels':48,'reviewer':'AI assistant','clinical_quality_approved':False,'cases':notes},ensure_ascii=False,indent=2))
    table=''
    for g,label in groups.items():
        s=summary['groups'][g]
        table+=f'<tr><td>{label}</td><td>{s["selected"]}</td><td>{s["old_knees"]}</td><td>{s["yolo_knees"]}</td><td>{s["yolo_two_films"]}/{s["selected"]}</td></tr>'
    ious=[i for r in validation['author_train_controls'] for i in r['best_iou_per_gt']]
    details={**identity,'author_control_mean_iou':statistics.mean(ious),'author_controls_are_training_sanity_check':True,
        'median_inference_plus_crop_seconds_cpu':.49860933562740684,'new_only_boxes':25,'old_only_boxes':1,'both_methods_boxes':69,
        'C39_entire_input_fraction_near_white':.4469875743415463,'comparison_boxes_are_not_accuracy':True}
    (root/'report_details.json').write_text(json.dumps(details,ensure_ascii=False,indent=2))
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>48 training films: knee crop comparison</title>
<style>:root{color-scheme:dark;--old:#ffaa33;--new:#00e1dc;--muted:#acbbc5}*{box-sizing:border-box}body{margin:0;background:#101820;color:#edf4f7;font:16px/1.7 system-ui,-apple-system,"PingFang SC",sans-serif}main{max-width:1440px;margin:auto;padding:36px 24px 70px}h1{font-size:clamp(25px,3vw,38px);line-height:1.3;margin:8px 0 16px}h2{font-size:22px;margin:28px 0 12px}p{max-width:1050px;margin:10px 0}.eyebrow,.muted{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.card{background:#1b2a34;border:1px solid #354954;border-radius:12px;padding:18px}.number{font-size:38px;line-height:1.25;font-weight:700}.old{color:var(--old)}.new{color:var(--new)}table{border-collapse:collapse;width:100%;margin:18px 0}th,td{text-align:left;padding:10px 14px;border-bottom:1px solid #354954}th{color:var(--muted);font-size:14px}tr:last-child{font-weight:650}.tablewrap{overflow:auto}.notice{border-left:3px solid #ffaa33;padding:12px 18px;background:#202d35;margin:20px 0}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:14px 0}button,select{font:inherit;background:#1b2a34;color:inherit;border:1px solid #516a77;border-radius:7px;padding:8px 14px;cursor:pointer}button:hover{background:#2d4654}button:disabled{opacity:.35;cursor:default}figure{margin:0}#comparison{width:100%;display:block;background:#101820;border:1px solid #354954;border-radius:8px}figcaption{color:var(--muted);font-size:14px;margin:9px 0}.casehead{display:flex;justify-content:space-between;gap:20px;align-items:center}.note{padding:16px;background:#1b2a34;border-radius:8px;min-height:85px}a{color:#7ce5df}details{border:1px solid #354954;padding:16px;border-radius:9px;margin:20px 0}summary{cursor:pointer;font-weight:650}pre{font-size:12px;overflow:auto;line-height:1.5}.legend{display:flex;gap:24px}.pill{padding:3px 10px;border-radius:12px;background:#263a46}.foot{margin-top:30px;font-size:13px;color:var(--muted)}@media(max-width:700px){main{padding:22px 12px}.cards{gap:8px}.card{padding:12px}.number{font-size:28px}th,td{padding:8px}#comparison{min-width:1000px}.imagewrap{overflow:auto}.casehead{display:block}}
</style></head><body><main>
<div class="eyebrow">2026-11-11 · 48 patients, one training film each · inference only</div>
<h1>YOLO focuses more on the joint and recovers more crops; missed detections and gray QC still need checks</h1>
<p>The author single-anchor + weight-decay YOLOv2 was downloaded and verified. Both methods use the same native gray image and outputs are shown at the same size. All 48 comparisons had an AI technical visual check.</p>
<div class="cards"><div class="card"><div class="muted">Existing geometric method · boxes output</div><div class="number old">70 / 96</div></div><div class="card"><div class="muted">Author YOLOv2 · boxes output</div><div class="number new">94 / 96</div></div><div class="card"><div class="muted">Films with both sides detected by YOLO</div><div class="number">46 / 48</div></div></div>
<p>YOLO added 25 boxes the old method did not output and missed 1 box the old method could output, a net gain of 24. Among the 69 knees output by both, the median YOLO crop area is about 37% of the old method, more focused on the joint. The number of boxes is not the number of usable samples, let alone KL accuracy.</p>
<div class="notice"><b>Failure cases to read together:</b>C05 misses image right; C39 is severely washed out, misses image right, and its image-left box cannot count as confirmed usable. Bright inputs such as C10, C31 and C38 should also be checked. Missing boxes were not filled by lowering the threshold.</div>
<div class="tablewrap"><table><thead><tr><th>Sample group</th><th>Films</th><th>Existing crops</th><th>YOLO crops</th><th>Films with both YOLO boxes</th></tr></thead><tbody>TABLE<tr><td>Total</td><td>48</td><td>70</td><td>94</td><td>46/48</td></tr></tbody></table></div>
<p class="muted">This batch deliberately enriches old-method failures and covers CR/DX/RG and several visits; 94/96 cannot estimate the success rate of the full data set. For the 40 films with cached old-method results, rerun boxes are all identical. There are no manual reference boxes, so localization accuracy is not reported.</p>
<h2>Case by case</h2><p>From left to right: both boxes on the original film, existing image-left crop, existing image-right crop, YOLO image-left crop, YOLO image-right crop. Image left = right knee and image right = left knee by the convention used here; the detector itself does not verify mirroring.</p>
<div class="legend"><span class="old">Orange: existing geometric crop</span><span class="new">Cyan: YOLO box, width and height expanded 1.3x</span></div>
<div class="controls"><select id="group" aria-label="Sample group"><option value="all">All 48</option><option value="old_two">Old: both knees</option><option value="old_one">Old: one side</option><option value="old_zero">Old: both failed</option><option value="new_position">Added by position split</option><option value="attention">Needs attention</option></select><select id="case" aria-label="Case ID"></select><button id="prev">← Previous</button><button id="next">Next →</button><span id="counter" class="muted"></span></div>
<div class="controls"><span class="muted">Examples:</span><button data-case="C01">Routine crop C01</button><button data-case="C27">One side recovered C27</button><button data-case="C37">Both sides recovered C37</button><button data-case="C05">Missed C05</button><button data-case="C39">Gray anomaly C39</button></div>
<div class="casehead"><h2 id="case-title"></h2><span id="counts" class="pill"></span></div><figure><div class="imagewrap"><img id="comparison" alt="Geometric and YOLO crops on the same film"></div><figcaption>Peripheral areas that may contain identifying text are masked only in the full-image preview. Analysis and single-knee crops use native pixels on the server; displays are scaled to 224 pixels and do not show the original resolution. Arrow keys also switch cases.</figcaption></figure><p id="note" class="note"></p>
<details><summary>Input adaptation, validation and scope</summary><p><b>Key compatibility:</b>Author H5 images are 0-255 floats and the loader casts to float32 before ToTensor, so the code never divides by 255 again. Following the actual author pipeline, mean=0.431 and std=0.0872 are applied directly. Both knees are detected in all three author training examples, with mean IoU CONTROL_IOU for the six boxes against the annotations; with an extra division by 255 none of the three examples has a box. This only shows the adaptation works; it is not an independent performance evaluation.</p><p>All 108 weight entries load strictly with no missing or extra keys; with the same weights the maximum absolute difference of the three outputs between the original author forward pass and the ported one is 0. The inverse coordinate mapping passes a known-affine check. The model file was checked against the ZIP member CRC and the returned SHA-256.</p><p>YOLO input geometry: resample by pixel spacing to 0.14 mm/px, center 2048x2560, then shrink to 256x320; score threshold 0.12, NMS 0.3, box width and height expanded 1.3x, then mapped back to the native image. C30 is zero-padded because it is too small. Both methods share the frozen DICOM display gray and 0.5/99.5 percentile normalization of this project; the author original DICOM gray chain is incomplete, so a pixel-exact reproduction of the author preprocessing is not claimed.</p><p>The 48 films come only from training patients of this project; author examples are limited to their train split intersected with this project train patients. No test targets were read and no new model was trained. The author detector may have seen some of these OAI images, so this batch does not show independent generalization or better KL performance. The full training crops have not been replaced and train_ready was not changed.</p><p>Median single-thread CPU time for inference plus cropping is about 0.50 s per case, excluding decoding, preparation and gallery generation.</p></details>
<details><summary>Reproducibility records and sources</summary><p>Model stored on <server> data directory:<code>/path/to/drai/experiments/chen_yolo_crop_compare_v1/assets/chen_yolov2_1wd.pth</code></p><p><a href="https://data.mendeley.com/datasets/56rmx5bjcr/1">Author public data and weights</a> · <a href="https://github.com/PingjunChen/GradingKneeOA/tree/dc19c2462111c3c5b27066e738fc11ddf57a6407">Author source at a fixed commit</a> · <a href="comparison.csv">Per-case statistics CSV</a> · <a href="visual_review.json">Per-case observations</a> · <a href="adapter_validation.json">Adaptation check</a></p><pre>DETAILS</pre></details>
<p class="foot">Conclusion: YOLO is worth using as the main crop candidate; missed detections need fallback or review, and gray anomalies need separate handling. All observations are technical visual checks, without physician reference annotations or clinical quality approval.</p></main>
<script>const data=DATA;const group=document.querySelector('#group'),picker=document.querySelector('#case');let shown=data,idx=0;function render(){const c=shown[idx];picker.value=c.case_id;document.querySelector('#comparison').src=c.case_id+'.png';document.querySelector('#case-title').textContent=c.case_id+' · '+c.group_zh+' · '+c.modality+' / '+c.visit;document.querySelector('#counts').textContent='existing  '+c.old_count+' knees / YOLO '+c.yolo_count+'  knees';document.querySelector('#note').textContent=c.note;document.querySelector('#counter').textContent=(idx+1)+' / '+shown.length;document.querySelector('#prev').disabled=idx===0;document.querySelector('#next').disabled=idx===shown.length-1;}function filter(){shown=data.filter(c=>group.value==='all'||(group.value==='attention'?c.needs_attention:c.group===group.value));idx=0;picker.replaceChildren(...shown.map(c=>{const o=document.createElement('option');o.value=c.case_id;o.textContent=c.case_id+' · '+c.group_zh;return o}));render();}function step(n){idx=Math.max(0,Math.min(shown.length-1,idx+n));render()}group.onchange=filter;picker.onchange=()=>{idx=shown.findIndex(c=>c.case_id===picker.value);render()};document.querySelector('#prev').onclick=()=>step(-1);document.querySelector('#next').onclick=()=>step(1);document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{group.value='all';filter();idx=shown.findIndex(c=>c.case_id===b.dataset.case);render()});document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')step(1);if(e.key==='ArrowLeft')step(-1)});filter();</script></body></html>'''
    page=page.replace('TABLE',table).replace('CONTROL_IOU',f'{statistics.mean(ious):.3f}').replace('DETAILS',html.escape(json.dumps(details,ensure_ascii=False,indent=2))).replace('DATA;',json.dumps(notes,ensure_ascii=False)+';')
    (root/'index.html').write_text(page)
    assert len(notes)==48 and all((root/(n['case_id']+'.png')).is_file() for n in notes)
    print(json.dumps({'report':str(root/'index.html'),'cases':48,'control_mean_iou':statistics.mean(ious),'visual_review_completed':True}))


if __name__=='__main__':main()
